@staticmethod
def _invalid(
    event: object,
    code: str = INVALID_EVENT,
    *,
    expected_sequence: int | None = None,
) -> dict[str, object]:
    event_id = symbol = None
    sequence = None
    if isinstance(event, dict):
        eid = event.get("event_id")
        if isinstance(eid, str) and eid != "":
            event_id = eid
        sym = event.get("symbol")
        if isinstance(sym, str) and sym != "":
            symbol = sym
        seq = event.get("sequence")
        if isinstance(seq, int) and not isinstance(seq, bool):
            sequence = seq
    result: dict[str, object] = {
        "event_id": event_id,
        "symbol": symbol,
        "sequence": sequence,
        "status": REJECTED,
        "rejection_code": code,
    }
    if expected_sequence is not None:
        result["expected_sequence"] = expected_sequence
    result["trades"] = []
    result["book_changes"] = {"bids": [], "asks": []}
    # An invalid event may reference a not-yet-known symbol; there is no
    # meaningful book to echo in that case.
    result["bids"] = []
    result["asks"] = []
    return result

def _submit_one(self, event: object, position: int) -> dict[str, object]:
    # ---- envelope validation (nothing is consumed on failure) --------
    if not isinstance(event, dict):
        return self._invalid(event)
    event_id = event.get("event_id")
    symbol = event.get("symbol")
    sequence = event.get("sequence")
    if not (
        isinstance(event_id, str)
        and event_id != ""
        and isinstance(symbol, str)
        and symbol != ""
        and isinstance(sequence, int)
        and not isinstance(sequence, bool)
        and sequence > 0
    ):
        return self._invalid(event)

    payload = event.get("event")
    event_type = event.get("type")
    if not isinstance(payload, dict) or not isinstance(event_type, str):
        return self._invalid(event)
    if event_type not in SUPPORTED_TYPES:
        return self._invalid(event)
    if payload.get("event_id") != event_id or payload.get("type") != event_type:
        # The wrapper and the baseline payload must identify the same event.
        return self._invalid(event)
    # Validate the full baseline schema up front, so malformed content is
    # classified INVALID_EVENT and reaches neither ordering nor the book.
    engine_probe = _BookEngine()
    if engine_probe._schema_error(payload) is not None:
        return self._invalid(event)

    state = self._state_for(symbol)

    # ---- per-symbol strict sequence ordering -------------------------
    expected = state.last_sequence + 1
    if sequence < expected:
        return self._invalid(event, OUT_OF_ORDER, expected_sequence=expected)
    if sequence > expected:
        return self._invalid(event, SEQUENCE_GAP, expected_sequence=expected)

    # ---- global idempotency ------------------------------------------
    content = canonical_json(payload).decode("utf-8")
    prior = self._events.get(event_id)
    if prior is not None:
        prior_symbol, prior_content = prior
        if prior_symbol != symbol or prior_content != content:
            # Nothing is rematched: a conflict consumes neither sequence
            # nor book state, so the correct event can follow immediately.
            return self._invalid(event, EVENT_ID_CONFLICT, expected_sequence=expected)
        bids, asks = state.engine.snapshot()
        return {
            "event_id": event_id,
            "symbol": symbol,
            "sequence": sequence,
            "status": DUPLICATE,
            "trades": [],
            "book_changes": {"bids": [], "asks": []},
            "bids": bids,
            "asks": asks,
        }

    # ---- committed application through the baseline engine ----------
    before_bids = dict(state.engine.level_totals()[0])
    before_asks = dict(state.engine.level_totals()[1])
    _eid, engine_result, reason, trades, _stp, _analysis, _position = (
        state.engine.handle_object_position(payload)
    )

    # The event id is committed from this point on, exactly mirroring the
    # baseline rule that a well-formed event occupies its id however the
    # business outcome ends.
    state.last_sequence = sequence
    state.seen[event_id] = content
    self._events[event_id] = (symbol, content)

    bids, asks = state.engine.snapshot()
    book_changes = self._book_changes(state.engine, before_bids, before_asks)
    if reason is None:
        out: dict[str, object] = {
            "event_id": event_id,
            "symbol": symbol,
            "sequence": sequence,
            "status": ACCEPTED,
            "result": engine_result,
            "trades": trades,
            "book_changes": book_changes,
            "bids": bids,
            "asks": asks,
        }
    else:
        out = {
            "event_id": event_id,
            "symbol": symbol,
            "sequence": sequence,
            "status": REJECTED,
            # Baseline business rejection codes (UNKNOWN_ORDER,
            # DUPLICATE_ORDER_ID, ...) are preserved verbatim.
            "rejection_code": reason,
            "trades": trades,
            "book_changes": book_changes,
            "bids": bids,
            "asks": asks,
        }
    return out

